'use strict';
(()=>{
const $=s=>document.querySelector(s),all=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),plain=s=>{const d=document.createElement('div');d.innerHTML=s;return d.textContent||''};
const lessons=COURSE.lessons,modules=COURSE.modules,byId=new Map(lessons.map(x=>[x.id,x])),byModule=id=>lessons.filter(l=>l.module===id),moduleOf=l=>modules.find(m=>m.id===l.module);
const KEY='predel-v1',fresh=()=>({completed:[],solved:[],bookmarks:[],notes:{},last:null,version:1});let storageWorks=true,state;
try{const d=JSON.parse(localStorage.getItem(KEY)||'null');state=d&&d.version===1?validateState(d):fresh()}catch{state=fresh();storageWorks=false}
function validateState(d){const filter=a=>Array.isArray(a)?[...new Set(a.filter(x=>typeof x==='string'&&byId.has(x)))]:[];const notes={};if(d.notes&&typeof d.notes==='object')for(const [id,v] of Object.entries(d.notes))if(byId.has(id)&&typeof v==='string')notes[id]=v.slice(0,50000);return {version:1,completed:filter(d.completed),solved:filter(d.solved),bookmarks:filter(d.bookmarks),notes,last:byId.has(d.last)?d.last:null}}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageWorks=true}catch{storageWorks=false;toast('Браузер не разрешил сохранение. Экспортируйте прогресс в «Моих записях».')}}
let cleanups=[],activeLesson=null,expanded=new Set(),toastTimer,practiceModule='all',practiceList=[],practiceRound=0;
const dispose=()=>{cleanups.forEach(fn=>fn());cleanups=[]};
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function typeset(){if(window.MathJax?.Hub)window.MathJax.Hub.Queue(['Typeset',window.MathJax.Hub,$('#main')]);else{const timer=setTimeout(typeset,250);cleanups.push(()=>clearTimeout(timer))}}
function progress(){const n=state.completed.length;$('#side-count').textContent=`${n} / ${lessons.length}`;$('#side-progress').style.width=(100*n/lessons.length)+'%'}
function navigation(){const route=location.hash.slice(1)||'home';all('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===route||route.startsWith(a.dataset.nav+'/')));$('#course-nav').innerHTML=modules.map((m,i)=>{const list=byModule(m.id),current=activeLesson?.module===m.id,open=expanded.has(m.id);return `<div class="nav-chapter"><button class="chapter-button ${current?'current':''}" data-module="${m.id}" aria-expanded="${open}" aria-controls="nav-${m.id}"><span class="num">${String(i+1).padStart(2,'0')}</span><span>${m.short||m.title}</span><span class="chev">${open?'−':'+'}</span></button><div id="nav-${m.id}" ${open?'':'hidden'}>${open?`<div class="chapter-lessons">${list.map(l=>`<a href="#lesson/${l.id}" ${activeLesson?.id===l.id?'aria-current="page"':''} class="${activeLesson?.id===l.id?'current':''}"><span class="lesson-dot">${state.completed.includes(l.id)?'✓':'·'}</span><span>${l.title}</span></a>`).join('')}</div>`:''}</div></div>`}).join('');all('[data-module]').forEach(b=>b.onclick=()=>{const id=b.dataset.module;if(expanded.has(id))expanded.delete(id);else expanded.add(id);navigation()});progress()}
function heading(eyebrow,title,desc){return `<div class="page-heading"><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${desc}</p></div>`}
function moduleCard(m,i){const list=byModule(m.id),done=list.filter(l=>state.completed.includes(l.id)).length;return `<a class="course-card ${m.id==='derivatives'?'featured':''}" href="#curriculum/${m.id}"><div class="card-top"><span class="module-icon">${m.symbol}</span>${m.id==='derivatives'?'<span class="card-badge">В ФОКУСЕ КУРСА</span>':`<span class="module-number">ГЛАВА ${String(i+1).padStart(2,'0')}</span>`}</div><h3>${m.title}</h3><p>${m.description}</p><div class="card-footer"><span>${list.length} уроков${done?' · '+done+' пройдено':''}</span><span>Изучить →</span></div></a>`}
function home(){const last=state.last&&byId.get(state.last),next=last||lessons.find(l=>!state.completed.includes(l.id))||lessons[0];$('#main').innerHTML=`<section class="hero"><div class="hero-content"><div class="eyebrow">ИНТЕРАКТИВНЫЙ УЧЕБНИК</div><h1>Понять изменение.<br><em>Научиться мыслить.</em></h1><p class="intro-text">Математический анализ от первых принципов.<br>От вещественных чисел до производных и количественных моделей — с интуицией, доказательствами и практикой.</p><div class="hero-actions"><a class="button" href="#lesson/${next.id}">${last?'Продолжить обучение':'Начать с основ'} <span>→</span></a><a class="button secondary" href="#curriculum">Программа курса</a></div><div class="meta-row"><span>По структуре Фихтенгольца</span><span>В своём темпе</span><span>На русском</span></div></div><div class="hero-visual"><div class="visual-head"><span>ОДНА ИДЕЯ. БЕСКОНЕЧНО МНОГО ПРИМЕНЕНИЙ.</span><span class="live-pill">Живой график</span></div><div class="visual-formula">Изменение становится понятным.</div><div id="hero-plot"></div><div class="mini-control"><label for="hero-h">h</label><input id="hero-h" type="range" min="0.02" max="1.1" step="0.01" value="0.65" aria-label="Шаг секущей h"><output id="hero-value">0,65</output></div><div class="visual-foot"><span>Сдвигайте ползунок. Приближайте секущую.</span><a href="#lesson/derivative">Почему это работает? ↗</a></div></div></section><section class="path-stats" aria-label="Обзор курса"><div class="stat"><div class="stat-value">${lessons.length} <span class="stat-label">содержательных уроков</span></div><div class="stat-label">${modules.length} глав · от оснований к приложениям</div></div><div class="stat"><div class="stat-value">${Object.keys(MathLabs.specs).length} <span class="stat-label">лабораторий</span></div><div class="stat-label">Увидеть математику в действии</div></div><div class="stat"><div class="stat-value"><strong>${Math.round(state.completed.length/lessons.length*100)}%</strong> <span class="stat-label">пути пройдено</span></div><div class="stat-label">${state.completed.length} изучено · ${state.solved.length} задач решено</div></div></section>${last?`<div class="saved-card"><div class="eyebrow">ВЫ ОСТАНОВИЛИСЬ ЗДЕСЬ</div><h3 style="margin:12px 0 7px"><a href="#lesson/${last.id}">${last.title} →</a></h3><span class="subtle">${moduleOf(last).title}</span></div>`:''}<div class="section-heading"><h2>Ваш маршрут в математическом анализе</h2><a class="text-link" href="#curriculum">Вся программа →</a></div><div class="course-grid">${modules.slice(0,6).map(moduleCard).join('')}</div><div class="quant-banner"><span class="quant-icon">∂V / ∂r</span><div><h3>Математика, которая работает в quant research</h3><p>От определения производной — к чувствительности, приближению и оптимизации.</p></div><a href="#labs/quant">Открыть quant-лабораторию ↗</a></div><div class="section-heading"><h2>Учиться, понимая каждый шаг</h2><a class="text-link" href="#sources">Как устроен учебник →</a></div><div class="course-grid"><div class="course-card"><div class="module-icon">?</div><h3 style="margin-top:18px">Сначала — хороший вопрос</h3><p>Начинаем с задачи, из которой естественно возникает новое понятие.</p></div><div class="course-card"><div class="module-icon">∴</div><h3 style="margin-top:18px">Затем — строгое доказательство</h3><p>Разбираем условия теорем, каждый переход и примеры, где условие нельзя убрать.</p></div><div class="course-card"><div class="module-icon">↗</div><h3 style="margin-top:18px">И ваша собственная практика</h3><p>Экспериментируйте с графиком, решайте задачу и записывайте объяснение своими словами.</p></div></div>`;MathLabs.hero($('#hero-plot'));$('#hero-h').oninput=e=>{const h=Number(e.target.value);MathLabs.hero($('#hero-plot'),h);$('#hero-value').textContent=MathLabs.fmt(h)}}
function curriculum(id){const selected=modules.find(m=>m.id===id),list=selected?[selected]:modules;$('#main').innerHTML=heading('ПРОГРАММА ПО ФИХТЕНГОЛЬЦУ',selected?selected.title:'От числа — к изменению','Порядок следует книге: сначала вещественные числа и последовательности, затем функции и дифференциальное исчисление. У каждого урока есть ссылка на соответствующие пункты.')+`<div class="filter-row"><a class="filter-button ${!selected?'active':''}" href="#curriculum">Вся программа</a><a class="filter-button" href="#lesson/rational">Начать последовательно →</a><a class="filter-button" href="#sources">Границы охвата и источники</a></div>`+list.map(m=>`<section class="module-block"><div class="module-head"><span class="module-icon">${m.symbol}</span><div><h2>${m.title}</h2><p>${m.book} · ${m.range}</p></div><span class="pill">${m.level==='overview'?'Обзорное продолжение':'Основной курс'}</span></div>${byModule(m.id).map(l=>`<a href="#lesson/${l.id}" class="lesson-row"><span class="row-num ${state.completed.includes(l.id)?'done-check':''}">${state.completed.includes(l.id)?'✓':String(lessons.indexOf(l)+1).padStart(2,'0')}</span><span>${l.title}</span><span class="row-meta">${l.minutes} мин <span aria-hidden="true">→</span></span></a>`).join('')}</section>`).join('')}
function exerciseHTML(l,prefix='ex'){const done=state.solved.includes(l.id);return `<div class="exercise" data-exercise="${l.id}"><span class="block-label">${done?'✓ РЕШЕНО':'САМОСТОЯТЕЛЬНАЯ ЗАДАЧА'}</span><div>${l.exercise.question}</div><form class="exercise-form"><label class="sr-only" for="${prefix}-${l.id}">Числовой ответ</label><input id="${prefix}-${l.id}" type="text" inputmode="decimal" autocomplete="off" placeholder="Число или дробь" aria-label="Числовой ответ" required><button class="button" type="submit">Проверить →</button></form><div class="feedback" role="status">${done?'Вы уже решили эту задачу. Можно проверить себя ещё раз.':''}</div><details><summary>Небольшая подсказка</summary><div>${l.exercise.hint}</div></details><details class="solution"><summary>Посмотреть полное решение</summary><div>${l.exercise.solution}</div></details></div>`}
function parseAnswer(s){s=s.trim().replace(/\s/g,'').replace(/,/g,'.').replace(/[−–]/g,'-');if(/^[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:e[+-]?\d+)?$/i.test(s))return Number(s);const m=s.match(/^([+-]?(?:\d+(?:\.\d*)?|\.\d+))\/([+-]?(?:\d+(?:\.\d*)?|\.\d+))$/);return m&&Number(m[2])!==0?Number(m[1])/Number(m[2]):NaN}
function bindExercises(){all('[data-exercise]').forEach(box=>{const l=byId.get(box.dataset.exercise),form=box.querySelector('form');form.onsubmit=e=>{e.preventDefault();const a=parseAnswer(form.querySelector('input').value),feedback=box.querySelector('.feedback');if(!Number.isFinite(a)){feedback.className='feedback incorrect';feedback.textContent='Введите конечное число: например 0,5, −2 или 1/6.';return}const correct=Math.abs(a-Number(l.exercise.answer))<=Number(l.exercise.tolerance||1e-6);feedback.className='feedback '+(correct?'correct':'incorrect');feedback.textContent=correct?'Верно. Теперь объясните, почему этот ответ следует из условий.':'Пока не совпало. Проверьте знак, область определения и строгие неравенства. Подсказка поможет выбрать первый шаг.';if(correct){if(!state.solved.includes(l.id))state.solved.push(l.id);box.querySelector('.block-label').textContent='✓ РЕШЕНО';save();progress();if($('#practice-score'))$('#practice-score').textContent=practiceList.filter(x=>state.solved.includes(x.id)).length+' / '+practiceList.length+' задач решено'}}})}
function lesson(id){const l=byId.get(id);if(!l){notFound();return}activeLesson=l;expanded.add(l.module);state.last=l.id;save();const m=moduleOf(l),idx=lessons.indexOf(l),prev=lessons[idx-1],next=lessons[idx+1],done=state.completed.includes(id);$('#main').innerHTML=`<div class="lesson-header"><div class="eyebrow">${m.title} · УРОК ${String(idx+1).padStart(2,'0')} ИЗ ${lessons.length}</div><h1>${l.title}</h1><div class="lesson-source">${l.source}${m.level==='overview'?' · Обзорное продолжение с доказательством выбранного результата':''}</div><div class="lesson-actions"><span class="lesson-meta">${l.minutes} мин чтения + эксперимент и практика</span><button id="bookmark" class="button secondary small" aria-pressed="${state.bookmarks.includes(id)}">${state.bookmarks.includes(id)?'✓ В закладках':'＋ В закладки'}</button><button id="complete" class="button small" aria-pressed="${done}">${done?'✓ Урок изучен':'Отметить изученным'}</button></div></div><div class="lesson-layout"><article class="prose"><section id="intuition"><h2><span class="section-index">01</span> Откуда возникает идея</h2><div class="content-block">${l.intuition}</div></section><section id="definition"><h2><span class="section-index">02</span> Сформулируем точно</h2><div class="definition"><span class="block-label">ОПРЕДЕЛЕНИЯ И ОБОЗНАЧЕНИЯ</span>${l.definition}</div><div class="theorem"><span class="block-label">ОСНОВНОЙ РЕЗУЛЬТАТ</span>${l.theorem}</div><details class="proof" open><summary>Почему это верно <span>Пошаговое доказательство</span></summary><div class="proof-content">${l.proof}</div></details></section><section id="example"><h2><span class="section-index">03</span> Разберём на примере</h2><div class="content-block">${l.example}</div><div class="pitfall"><span class="block-label">ГДЕ ЛЕГКО ОШИБИТЬСЯ</span>${l.pitfall}</div></section><section id="experiment"><h2><span class="section-index">04</span> Увидеть своими глазами</h2><div id="lesson-lab"></div></section><section id="quant"><h2><span class="section-index">05</span> Связь с количественными моделями</h2><div class="quant-note">${l.quant}</div></section><section id="exercise"><h2><span class="section-index">06</span> Проверьте понимание</h2>${exerciseHTML(l)}<div class="pitfall" style="background:#f0f3eb;border-color:#e1e7d8"><span class="block-label">ДЛЯ ГЛУБОКОГО ОСВОЕНИЯ</span>Закройте доказательство и восстановите его самостоятельно. Назовите все условия результата и объясните на примере из урока, что может нарушиться без одного из них. Числовой ответ проверяется автоматически; качество доказательства оценивайте по логике каждого перехода.</div></section><section id="notes"><h2><span class="section-index">07</span> Объясните своими словами</h2><label class="notes-label" for="lesson-notes">Главная идея, собственное доказательство, оставшиеся вопросы</label><textarea id="lesson-notes" class="notes-area" placeholder="Я понял, почему… Осталось разобраться…">${esc(state.notes[id]||'')}</textarea><div class="save-status" id="note-status">${storageWorks?'Заметки сохраняются только в этом браузере.':'Хранилище недоступно: экспортируйте записи перед закрытием.'}</div></section><div class="lesson-navigation">${prev?`<a href="#lesson/${prev.id}"><small>← ПРЕДЫДУЩИЙ УРОК</small>${prev.title}</a>`:'<a href="#curriculum"><small>← ПРОГРАММА</small>Все главы</a>'}${next?`<a href="#lesson/${next.id}"><small>СЛЕДУЮЩИЙ УРОК →</small>${next.title}</a>`:'<a href="#practice"><small>ЗАКРЕПИТЬ ЗНАНИЯ →</small>Смешанная практика</a>'}</div></article><nav class="toc" aria-label="Содержание урока"><div class="toc-label">В ЭТОМ УРОКЕ</div><a href="#intuition" data-anchor="intuition">01 · Интуиция</a><a href="#definition" data-anchor="definition">02 · Теория и доказательство</a><a href="#example" data-anchor="example">03 · Пример и ошибки</a><a href="#experiment" data-anchor="experiment">04 · Эксперимент</a><a href="#quant" data-anchor="quant">05 · Quant-контекст</a><a href="#exercise" data-anchor="exercise">06 · Практика</a><a href="#notes" data-anchor="notes">07 · Мои заметки</a><div style="margin-top:17px"><a href="#curriculum/${m.id}">← К главе</a></div></nav></div>`;
 cleanups.push(MathLabs.mount($('#lesson-lab'),l.lab,l.labPrompt));bindExercises();all('[data-anchor]').forEach(a=>a.onclick=e=>{e.preventDefault();document.getElementById(a.dataset.anchor).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'})});$('#bookmark').onclick=()=>{const on=state.bookmarks.includes(id);state.bookmarks=on?state.bookmarks.filter(x=>x!==id):[...state.bookmarks,id];save();$('#bookmark').textContent=on?'＋ В закладки':'✓ В закладках';$('#bookmark').setAttribute('aria-pressed',String(!on));toast(on?'Закладка удалена':'Урок сохранён в «Моих записях»')};$('#complete').onclick=()=>{const on=state.completed.includes(id);state.completed=on?state.completed.filter(x=>x!==id):[...state.completed,id];save();$('#complete').textContent=on?'Отметить изученным':'✓ Урок изучен';$('#complete').setAttribute('aria-pressed',String(!on));navigation();toast(on?'Отметка снята':'Урок отмечен. Переходите дальше, когда сможете восстановить доказательство.')};$('#lesson-notes').oninput=e=>{state.notes[id]=e.target.value;save();$('#note-status').textContent=storageWorks?'Сохранено в этом браузере':'Запись хранится в текущей вкладке. Сделайте экспорт.'};typeset();}
function labs(id){const spec=MathLabs.specs[id];if(spec){$('#main').innerHTML=heading('ЛАБОРАТОРИЯ МАТЕМАТИЧЕСКОГО АНАЛИЗА',spec.title,'Меняйте один параметр за раз, сначала предсказывайте результат, затем проверяйте гипотезу на графике.')+'<div id="standalone-lab" style="max-width:900px"></div><div class="section-heading"><h2>Изучить математическое обоснование</h2><a class="text-link" href="#labs">Все лаборатории →</a></div><div class="module-block">'+lessons.filter(l=>l.lab===id).map(l=>`<a class="lesson-row" href="#lesson/${l.id}"><span class="row-num">${lessons.indexOf(l)+1}</span><span>${l.title}</span><span class="row-meta">Открыть →</span></a>`).join('')+'</div>';cleanups.push(MathLabs.mount($('#standalone-lab'),id));return}$('#main').innerHTML=heading('ПРОВЕРЯЙТЕ ГИПОТЕЗЫ','Математика в движении','Наглядность помогает найти идею. Доказательство объясняет, почему она работает для всех допустимых случаев.')+`<div class="lab-grid">${Object.entries(MathLabs.specs).map(([id,s])=>`<a class="lab-card" href="#labs/${id}"><span class="lab-symbol">${s.symbol}</span><h3>${s.title}</h3><p>${s.desc}</p><span class="text-link">Начать эксперимент →</span></a>`).join('')}</div>`}
function practice(){const pool=practiceModule==='all'?lessons:byModule(practiceModule);if(!practiceList.length||!practiceList.every(l=>pool.includes(l))){practiceList=pool.slice(0,5)}$('#main').innerHTML=heading('САМОСТОЯТЕЛЬНАЯ РАБОТА','Из понимания — в навык','Решите задачи без подсказок, затем объясните ход решения. Ответы принимают десятичную запятую, точку и простые дроби.')+`<div class="filter-row"><label for="practice-module" class="subtle">Раздел</label><select class="practice-select" id="practice-module"><option value="all">Весь учебник</option>${modules.map(m=>`<option value="${m.id}"${practiceModule===m.id?' selected':''}>${m.title}</option>`).join('')}</select><button id="practice-refresh" class="button secondary small">Другой набор ↻</button><span id="practice-score" class="pill">${practiceList.filter(x=>state.solved.includes(x.id)).length} / ${practiceList.length} задач решено</span></div><p class="subtle">Статус «решено» сохраняется. Подсказки и раскрытие решения сами по себе не отмечают задачу выполненной.</p><div style="max-width:850px">${practiceList.map((l,i)=>`<section class="practice-item"><div class="section-heading"><h3 style="margin:0">${i+1}. ${l.title}</h3><a class="text-link" href="#lesson/${l.id}">К уроку →</a></div>${exerciseHTML(l,'practice')}</section>`).join('')}</div>`;$('#practice-module').onchange=e=>{practiceModule=e.target.value;practiceList=[];practice();typeset()};$('#practice-refresh').onclick=()=>{practiceRound++;const offset=(practiceRound*5)%pool.length;practiceList=Array.from({length:Math.min(5,pool.length)},(_,i)=>pool[(offset+i)%pool.length]);practice();typeset()};bindExercises();typeset()}
function saved(){const ids=lessons.filter(l=>state.bookmarks.includes(l.id)||state.notes[l.id]?.trim());$('#main').innerHTML=heading('ЛИЧНАЯ РАБОЧАЯ ТЕТРАДЬ','Ваши идеи и открытия','Закладки, заметки и прогресс хранятся в этом браузере. Экспорт позволяет сохранить резервную копию и перенести её на другое устройство.')+`<div class="filter-row"><button class="button secondary small" id="export">↓ Экспортировать прогресс</button><label class="button secondary small" for="import">↑ Импортировать копию</label><input id="import" type="file" accept="application/json,.json" hidden><span class="pill">${state.completed.length} уроков изучено · ${state.solved.length} задач решено</span></div><p class="subtle">Импорт объединяет отметки и закладки. Для совпадающих уроков импортированные заметки заменят текущие.</p>${ids.length?ids.map(l=>`<section class="saved-card"><div class="section-heading" style="margin:0 0 10px"><h3 style="margin:0"><a href="#lesson/${l.id}">${l.title} →</a></h3>${state.bookmarks.includes(l.id)?'<span class="pill">Закладка</span>':''}</div>${state.notes[l.id]?`<p>${esc(state.notes[l.id])}</p>`:'<p>Откройте урок, чтобы добавить собственное объяснение.</p>'}</section>`).join(''):'<div class="empty">Здесь появятся ваши закладки и заметки.<br>Откройте урок и сохраните важную идею своими словами.</div>'}`;
 $('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='predel-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Копия прогресса подготовлена')};$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>5e6){toast('Файл слишком большой. Выберите JSON-копию прогресса до 5 МБ.');return}try{const raw=JSON.parse(await f.text());if(raw.version!==1||!Array.isArray(raw.completed))throw Error('format');const d=validateState(raw);state.completed=[...new Set([...state.completed,...d.completed])];state.solved=[...new Set([...state.solved,...d.solved])];state.bookmarks=[...new Set([...state.bookmarks,...d.bookmarks])];state.notes={...state.notes,...d.notes};state.last=d.last||state.last;save();saved();navigation();toast('Прогресс и записи импортированы')}catch{toast('Не удалось прочитать копию. Нужен JSON-файл экспорта этого учебника.')}}}
function sources(){const vids=COURSE.sources.videos;$('#main').innerHTML=heading('ИСТОЧНИКИ И МЕТОДИКА','Строгость книги. Ясность объяснения.','Учебник написан своими словами на основе предоставленного архива. Мотивация и визуальные идеи помогают освоить строгую последовательность математического анализа.')+`<div class="source-grid"><section class="source-card full"><h2>Как использована книга Фихтенгольца</h2><p>Основа — «Курс дифференциального и интегрального исчисления», три файла Fixt1.pdf, Fixt2.pdf и Fixt3.pdf из папки «Фихтенгольца - курс-книга». Изучены оглавления всех томов; ключевые определения и теоремы первого тома сверены по сканам. В отчёте проверки отдельно указано, где проверено оглавление, а где основной текст.</p><p><b>Подробное ядро:</b> введение и главы I–IV, пункты 1–158; 40 уроков с последовательным объяснением предварительных тем и дифференциального исчисления. <b>Дальнейший основной маршрут:</b> главы V–VII и дополнение первого тома; 18 уроков. <b>Обзорное продолжение:</b> главы VIII–XX и дополнение; 20 уроков с основными определениями, выбранными доказательствами и задачами.</p><p>Уроки объединяют связанные пункты книги. Это самостоятельный учебный маршрут, а не постраничное воспроизведение и не замена всех доказательств трёх томов. Точные диапазоны указаны в каждом уроке. В частности, общее многомерное продолжение и отдельные глубокие результаты интегрального анализа даны с ограниченным объёмом доказательства.</p><p>В архивном скане обнаружен повтор: PDF-страница 199 первого тома содержит печатную страницу 170 вместо ожидаемой 190. Поэтому ссылки даются на печатные страницы и номера пунктов, без ненадёжного автоматического перехода по PDF.</p><a href="course-plan.json" download>Скачать подробную программу (JSON) ↓</a> · <a href="source-review.json" download>Отчёт проверки источников ↓</a></section><section class="source-card"><h2>Объяснения Shiz</h2><p>В центре — метод «придумать понятие»: начать с задачи, проверить естественную попытку, обнаружить её недостаток и построить точное определение. Аналогии и формулировки здесь авторские, без имитации речи или копирования транскриптов.</p><p>Неформальные утверждения проверяются отдельно: эквивалентности нельзя безусловно подставлять в разности, а дифференциал не равен фактическому приращению.</p><ul>${vids.filter(v=>v.author==='Shiz').map(v=>`<li><a href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noreferrer">${v.title}</a></li>`).join('')}</ul></section><section class="source-card"><h2>Трушин и 3Blue1Brown</h2><p>Транскрипты Бориса Трушина помогли выстроить внимание к гипотезам теорем, контрпримерам и логике доказательства. Материалы 3Blue1Brown — связать формулы с изменением площадей, растяжениями и приближениями.</p><ul>${vids.filter(v=>v.author!=='Shiz').map(v=>`<li><a href="https://www.youtube.com/watch?v=${v.id}" target="_blank" rel="noreferrer">${v.author}: ${v.title}</a></li>`).join('')}</ul></section><section class="source-card"><h2>Как проходить урок</h2><ol><li>Сначала попробуйте ответить на исходный вопрос без формул.</li><li>Прочитайте определение и выпишите все условия теоремы.</li><li>Разберите доказательство, затем восстановите его по памяти.</li><li>Предскажите результат эксперимента до движения ползунка.</li><li>Решите задачу и сохраните собственное объяснение.</li></ol><p>Среднее время в карточке — ориентир для чтения. Полное освоение включает повторное доказательство и практику, поэтому может занять значительно больше.</p></section><section class="source-card"><h2>Прозрачность моделей и данных</h2><p>Графики — иллюстрации точных математических моделей. Конечная сетка и вычисления с плавающей точкой не заменяют доказательства предела. Quant-примеры объясняют чувствительности и оптимизацию, не используют текущие рыночные данные.</p><p>Сайт не отправляет ответы и заметки на сервер. Сохранение происходит в localStorage браузера; приватный режим и очистка данных могут удалить записи. Используйте экспорт.</p><p>Формулы отображаются локальной библиотекой MathJax 2.7.9, включённой с лицензией Apache 2.0. Сайт работает без CDN и внешних шрифтов.</p><a href="mathjax/LICENSE-APACHE-2.0.txt">Лицензия MathJax</a></section></div>`}
function notFound(){$('#main').innerHTML=heading('СТРАНИЦА НЕ НАЙДЕНА','Вернёмся к маршруту','Такого урока нет в программе.')+'<a class="button" href="#curriculum">Открыть программу →</a>'}
function syncNavAccess(){const mobile=matchMedia('(max-width:720px)').matches;$('#sidebar').inert=mobile&&!document.body.classList.contains('menu-open')}
function closeMenu(){const restore=document.body.classList.contains('menu-open')&&$('#sidebar').contains(document.activeElement);document.body.classList.remove('menu-open');$('#scrim').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');syncNavAccess();if(restore)$('#menu-toggle').focus()}
function route(){dispose();activeLesson=null;closeMenu();const hash=location.hash.slice(1)||'home',[page,id]=hash.split('/');if(page==='lesson')lesson(id);else if(page==='curriculum')curriculum(id);else if(page==='labs')labs(id);else if(page==='practice')practice();else if(page==='saved')saved();else if(page==='sources')sources();else if(page==='home')home();else notFound();const titles={home:'Мой учебник',curriculum:'Программа курса',labs:'Лаборатории',practice:'Практика',saved:'Мои записи',sources:'Источники'};$('#breadcrumb').innerHTML=`<a href="#home">Математический анализ</a> <span>/</span> ${activeLesson?moduleOf(activeLesson).title:titles[page]||'Учебник'}`;document.title=(activeLesson?.title||titles[page]||'Учебник')+' — Предел';navigation();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});updateReading()}
const searchIndex=lessons.map(l=>({l,text:plain([l.title,l.intuition,l.definition,l.theorem,l.proof,l.example,l.quant].join(' '))}));
function search(query=''){const q=query.trim().toLocaleLowerCase('ru'),matches=q?searchIndex.filter(x=>x.text.toLocaleLowerCase('ru').includes(q)):searchIndex.filter(x=>['rational','sequence','derivative','chain','taylor-peano','newton'].includes(x.l.id));$('#search-results').innerHTML=matches.length?matches.slice(0,30).map(({l,text})=>{const at=q?text.toLocaleLowerCase('ru').indexOf(q):0,start=Math.max(0,at-65),snippet=text.slice(start,start+170);return `<a class="search-result" href="#lesson/${l.id}"><small>${moduleOf(l).title}</small><strong>${l.title}</strong>${q?`<p>${start?'…':''}${esc(snippet)}…</p>`:''}</a>`}).join(''):`<div class="empty">Ничего не найдено. Попробуйте «предел», «Коши» или «производная».</div>`;all('.search-result').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
function openSearch(){search();$('#search-input').value='';$('#search-dialog').showModal();$('#search-input').focus()}
$('#search-open').onclick=openSearch;$('#search-close').onclick=()=>$('#search-dialog').close();$('#search-input').oninput=e=>search(e.target.value);$('#search-dialog').onclick=e=>{if(e.target===$('#search-dialog')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)e.target.close()}};document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape')closeMenu()});$('#menu-toggle').onclick=()=>{const open=document.body.classList.toggle('menu-open');$('#scrim').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',String(open));syncNavAccess()};$('#scrim').onclick=closeMenu;$('#focus-toggle').onclick=()=>{const on=document.body.classList.toggle('focus');$('#focus-toggle').setAttribute('aria-pressed',String(on));toast(on?'Режим чтения включён':'Навигация возвращена')};
const bar=document.createElement('div');bar.className='reading-progress';bar.setAttribute('aria-hidden','true');bar.innerHTML='<i></i>';document.body.appendChild(bar);function updateReading(){const available=document.documentElement.scrollHeight-innerHeight;bar.firstChild.style.width=activeLesson&&available>0?Math.min(100,scrollY/available*100)+'%':'0%'}window.addEventListener('scroll',updateReading,{passive:true});window.addEventListener('hashchange',route);window.addEventListener('resize',syncNavAccess);window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{state=validateState(JSON.parse(e.newValue));navigation()}catch{}}});window.Predel={parseAnswer,getState:()=>structuredClone(state),lessonCount:lessons.length};route();
})();
